# owner: platform
"""Seating charts laid out row by row."""

from typing import List

from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _check(students: List[Student], seats: int) -> None:
    if seats <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")


def _sort_key(student: Student) -> tuple:
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())


# ---
def seating_rows(
    students: List[Student], seats_per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    _check(students, seats_per_row)
    ordered = sorted(students, key=_sort_key)
    step = seats_per_row
    chunks = [ordered[i:i + step] for i in range(0, len(ordered), step)]
    return [_line(n, row) for n, row in enumerate(chunks, 1)]


def _line(number: int, row: List[Student]) -> str:
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"
EOF
cat > tests/test_seating.py <<'EOF'
# owner: platform
import unittest

from rosterkit.errors import ProjectError
from rosterkit.models import Student
from rosterkit.seating import seating_rows


def make(last, first):
    return Student(last + first, last, first, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Abbott", "Ana")
        ]

    def test_sorted_and_chunked(self):
        rows = seating_rows(self.people, 2)
        self.assertEqual(rows, [
            "Row 1: Abbott, Ana | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    def test_case_insensitive_sort(self):
        people = [make("zed", "A"), make("Young", "B")]
        rows = seating_rows(people, 5)
        self.assertEqual(rows, ["Row 1: Young, B | zed, A"])

    def test_bad_seat_counts(self):
        for seats in (0, -3):
            with self.assertRaises(ProjectError):
                seating_rows(self.people, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
